// A mounted skill's DESCRIPTION is in the window from the first token of the session,
// whether or not the skill is ever loaded — the body is not. So the description is a
// cost the corpus imposes the way its prose is, and the only one a reader can compare
// against something: the skills the same session got from outside the corpus, which
// are priced the same way and which no pack controls.
test('prices the skill descriptions it mounts, per skill, against the ones from elsewhere', () => {
  const corpus = makeCorpus({ alpha: { skills: ['one', 'two'] } });
  const skill = (name, descWords) => `---\nname: ${name}\ndescription: ${words(descWords)}\n---\n# skill\n`;
  for (const [name, n] of [['one', 15], ['two', 15]]) {
    mkdirSync(join(corpus, 'packs', 'alpha', 'skills', name), { recursive: true });
    writeFileSync(join(corpus, 'packs', 'alpha', 'skills', name, 'SKILL.md'), skill(name, n));
  }
  const project = makeProject({ packs: ['alpha'] });
  // The skills a session carries that the corpus did not put there live under the
  // person's own `~/.claude/skills`, at whatever depth a marketplace nests them.
  const home = mkdtempSync(join(tmpdir(), 'claudinite-home-'));
  const outside = join(home, '.claude', 'skills', 'synced', 'vendor', 'theirs');
  mkdirSync(outside, { recursive: true });
  writeFileSync(join(outside, 'SKILL.md'), skill('theirs', 60));
  try {
    // 30 description words over 2 skills is 40 tokens at the corpus's ratio, 20 each;
    // the one outside skill's 60 words are 80. The comparison is the point of the facet.
    assert.match(
      run(corpus, project, { HOME: home }),
      /2 regular skills, 40 skill-description tokens \(20 each; 80 each for the 1 skill from elsewhere\), /,
    );
    // Nothing readable outside leaves the corpus's own figure standing alone, never a zero.
    assert.match(
      run(corpus, project, { HOME: mkdtempSync(join(tmpdir(), 'claudinite-nohome-')) }),
      /2 regular skills, 40 skill-description tokens \(20 each\)\./,
    );
  } finally { removeTree(corpus); removeTree(project); removeTree(home); }
});

