node -e "
const { readFileSync, existsSync } = require('node:fs');
const { join } = require('node:path');
(async () => {
  const root = '/home/user/Claudinite';
  const { loadPacks, isActive } = await import('./engine/pack_loader/pack-registry.mjs');
  const { countWords, estimateTokens } = await import('./engine/pack_loader/token-estimate.mjs');
  const declared = JSON.parse(readFileSync(join(root, '.claudinite-settings.json'), 'utf8')).packs;
  const packs = await loadPacks({ localRoot: root, session: true });
  let counted = 0, skipped = 0;
  for (const p of packs) {
    if (!isActive(p, { packs: declared })) continue;
    const w = p.prose && existsSync(join(p.dir, p.prose)) ? countWords(readFileSync(join(p.dir, p.prose),'utf8')) : 0;
    const tag = p.temp ? 'TEMP (excluded)' : 'counted';
    if (p.temp) skipped += w; else counted += w;
    console.log(String(estimateTokens(w)).padStart(6), p.id.padEnd(32), tag);
  }
  console.log('---');
  console.log('counted total :', estimateTokens(counted), '->', estimateTokens(counted,100));
  console.log('temp excluded :', estimateTokens(skipped));
  console.log('if included   :', estimateTokens(counted+skipped,100));
})();"

