13	// The SESSION SUMMARY step: the one line a session opens with, stating what
14	// actually loaded — which repo, the active packs, the token weight of the prose
15	// injected, the guards and checks armed, the skills mounted. It exists because every other session-start step
16	// reports that the MACHINERY ran; none of them says how much landed, which is the
17	// only part a person can sanity-check.
18	//
19	// The contract under test is generic: count what is active, let a pack add one
20	// facet of its own through its manifest, and never fail a session. Core names no
21	// pack to get a facet, so the fixtures below are nonsense packs, deliberately.
22	function makeCorpus(packs) {
23	  const root = mkdtempSync(join(tmpdir(), 'claudinite-corpus-'));
24	  mkdirSync(join(root, 'packs'), { recursive: true });
25	  mkdirSync(join(root, 'engine', 'pack_loader'), { recursive: true });
26	  // The whole loader directory — see mount-skills.test.mjs: an enumerated subset
27	  // breaks fail-soft the day the registry gains a sibling.
28	  cpSync(join(REPO_ROOT, 'engine', 'pack_loader'), join(root, 'engine', 'pack_loader'), { recursive: true });
29	  // pack-schema validates a version against the engine's version module, which sits
30	  // beside pack_loader in the real tree.
31	  cpSync(join(REPO_ROOT, 'engine', 'version.mjs'), join(root, 'engine', 'version.mjs'));
32	  // Where a member's settings live: the loader resolves the declaration through it.
33	  for (const f of ['settings-file.mjs', 'settings-file-names.mjs']) cpSync(join(REPO_ROOT, 'engine', f), join(root, 'engine', f));
34	  for (const [id, { proseText, manifestSource, ...manifest }] of Object.entries(packs)) {
35	    const dir = join(root, 'packs', id);
36	    mkdirSync(dir, { recursive: true });
37	    const base = { id, detect: null, worldRules: [], ruleRoutingGuidance: { belongs: `whatever ${id} owns`, excludes: `whatever ${id} does not own` }, ...manifest };
38	    writeFileSync(
39	      join(dir, 'pack.mjs'),
40	      manifestSource
41	        ? manifestSource(JSON.stringify(base))
42	        : `export default ${JSON.stringify(base)};\n`,
43	    );
44	    if (proseText !== undefined) writeFileSync(join(dir, base.prose ?? 'RULES.md'), proseText);
45	  }
46	  return root;
47	}
48	
49	function makeProject(declaration) {
50	  const root = mkdtempSync(join(tmpdir(), 'claudinite-proj-'));
51	  writeFileSync(join(root, '.claudinite-settings.json'), `${JSON.stringify(declaration, null, 2)}\n`);
52	  return root;
53	}
54	
55	function run(corpus, project, env = {}) {
56	  const r = spawnSync('node', [join(corpus, 'engine', 'pack_loader', 'session-summary.mjs')], {
57	    encoding: 'utf8',
58	    // A CI runner names its own repo in the environment; a fixture project says
59	    // nothing about a repo unless the test gives it one.
60	    env: { ...process.env, GITHUB_REPOSITORY: '', CLAUDE_PROJECT_DIR: project, ...env },
61	  });
62	  // A non-zero exit makes Claude Code DISCARD the orchestrator's whole stdout, so
63	  // this step may never produce one — whatever it found.
64	  assert.equal(r.status, 0, r.stderr);
65	  return r.stdout;
66	}
