68	// A rule needs only an id and a run to be a rule (pack-schema's isRuleArray), and
69	// the manifest is JSON-serialized into the fixture — so rules arrive as source.
70	// A guard is a rule whose declaration has `scope: "action"` — the shape a declared
71	// `guardToolCalls` check loads to; `rules(n)` gives plain ones, `rules(n, g)` adds g guards.
72	const ruleSource = (n, spec) => JSON.stringify(Array.from({ length: n }, (_, i) => ({ id: `${spec ? 'g' : 'r'}${i}`, ...(spec ? { spec } : {}) })));
73	const rules = (n, guards = 0) => ({ manifestSource: (json) => `const rules = [...${ruleSource(n)}, ...${ruleSource(guards, { scope: 'action' })}].map((r) => ({ ...r, run: () => {} }));\nexport default { ...${json}, workRules: rules };\n` });
74	
75	// Prose is estimated through WORDS (roughly 0.75 of them per token), so a fixture
76	// says how many words it is, not how many bytes.
77	const words = (n) => Array.from({ length: n }, (_, i) => `word${i}${i % 12 === 11 ? '\n' : ''}`).join(' ');
