    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (entry.isDirectory()) walk(join(dir, entry.name), depth + 1);
      else if (entry.name === 'SKILL.md') found.push(dir);
    }
  };
  walk(root, 0);
  return found;
}

